var testOp = require( '@stdlib/utils/json-patch/ops/test-op' );
var validate = require( '@stdlib/utils/json-patch/validate' );
var apply = require( '@stdlib/utils/json-patch/apply' );
var shallowClone = require( './../_lib/shallow_clone.js' );


// FIXTURES //

var largeDocFixture = require( './fixtures/large_doc.json' );
var complexPatchFixture = require( './fixtures/patch_complex.json' );
