// ===========================================================================

// add

// ===========================================================================

tape( 'add: main export is a function', function test( t ) {
	t.strictEqual( typeof add, 'function', 'main export is a function' );
	t.end();
});

tape( 'add: adds a property to an object', function test( t ) {
	var doc = {
		'foo': 'bar'
	};
	var out = add( doc, '/baz', 'qux' );
	t.strictEqual( out.baz, 'qux', 'returns expected value' );
	t.strictEqual( out.foo, 'bar', 'returns expected value' );
	t.end();
});

tape( 'add: replaces an existing object property', function test( t ) {
	var doc = {
		'foo': 'bar'
	};
	var out = add( doc, '/foo', 'baz' );
	t.strictEqual( out.foo, 'baz', 'returns expected value' );
	t.end();
});

tape( 'add: inserts into an array at a given index', function test( t ) {
	var doc = {
		'foo': [ 1, 2, 3 ]
	};
	var out = add( doc, '/foo/1', 99 );
	t.deepEqual( out.foo, [ 1, 99, 2, 3 ], 'returns expected value' );
	t.end();
});

tape( 'add: appends to an array using the `-` token', function test( t ) {
	var doc = {
		'foo': [ 1, 2, 3 ]
	};
	var out = add( doc, '/foo/-', 4 );
	t.deepEqual( out.foo, [ 1, 2, 3, 4 ], 'returns expected value' );
	t.end();
});

tape( 'add: replaces the entire document at root', function test( t ) {
	var doc = {
		'foo': 'bar'
	};
	var out = add( doc, '', {
		'new': 'doc'
	});
	t.deepEqual( out, {
		'new': 'doc'
	}, 'returns expected value' );
	t.end();
});

tape( 'add: adds a nested property', function test( t ) {
	var doc = {
		'a': {
			'b': {}
		}
	};
	var out = add( doc, '/a/b/c', 42 );
	t.strictEqual( out.a.b.c, 42, 'returns expected value' );
	t.end();
});

tape( 'add: does not mutate the original document', function test( t ) {
	var doc = {
		'foo': 'bar'
	};
	var out = add( doc, '/baz', 'qux' );
	t.notEqual( doc, out, 'returns expected value' );
	t.strictEqual( doc.baz, void 0, 'returns expected value' );
	t.end();
});

tape( 'add: inserts at index 0 of an array', function test( t ) {
	var doc = {
		'foo': [ 'a', 'b' ]
	};
	var out = add( doc, '/foo/0', 'z' );
	t.deepEqual( out.foo, [ 'z', 'a', 'b' ], 'returns expected value' );
	t.end();
});

tape( 'add: inserts at index equal to array length (append)', function test( t ) {
	var doc = {
		'foo': [ 'a', 'b' ]
	};
	var out = add( doc, '/foo/2', 'c' );
	t.deepEqual( out.foo, [ 'a', 'b', 'c' ], 'returns expected value' );
	t.end();
});

tape( 'add: clones the incoming value (prevents reference sharing)', function test( t ) {
	var value = {
		'x': 1
	};
	var doc = {
		'foo': {}
	};
	var out = add( doc, '/foo/bar', value );
	t.deepEqual( out.foo.bar, {
		'x': 1
	}, 'returns expected value' );
	t.notEqual( out.foo.bar, value, 'returns expected value' );
	t.end();
});

tape( 'add: throws on invalid first argument', function test( t ) {
	t.throws( function badValue() {
		add( 'string', '/foo', 1 );
	}, TypeError, 'throws an error' );
	t.end();
});

tape( 'add: throws when path traverses a primitive', function test( t ) {
	t.throws( function badValue() {
		add({
			'foo': 'bar'
		}, '/foo/baz', 1 );
	}, Error, 'throws an error' );
	t.end();
});

