tape( 'stress test: 150+ sequential operations patch', function test( t ) {
	var patch;
	var base;
	var out;
	var i;

	base = {
		'counters': [],
		'map': {},
		'history': []
	};

	patch = [];
	for ( i = 0; i < 50; i++ ) {
		patch.push({
			'op': 'add',
			'path': '/counters/-',
			'value': i
		});
		patch.push({
			'op': 'add',
			'path': '/map/key_' + i,
			'value': 'val_' + i
		});
	}
	for ( i = 0; i < 25; i++ ) {
		patch.push({
			'op': 'replace',
			'path': '/map/key_' + i,
			'value': 'new_val_' + i
		});
		patch.push({
			'op': 'test',
			'path': '/map/key_' + i,
			'value': 'new_val_' + i
		});
	}
	for ( i = 0; i < 10; i++ ) {
		patch.push({
			'op': 'copy',
			'from': '/map/key_' + i,
			'path': '/history/-'
		});
	}
	for ( i = 0; i < 5; i++ ) {
		patch.push({
			'op': 'remove',
			'path': '/counters/0'
		});
	}

	out = apply( base, patch );

	t.strictEqual( out.counters.length, 45, 'counters has expected length after adds and removes' );
	t.strictEqual( out.counters[ 0 ], 5, 'first counter shifted after 5 removes' );
	t.strictEqual( out.history.length, 10, 'history has expected length after copies' );
	t.strictEqual( out.history[ 0 ], 'new_val_0', 'copied values match' );
	t.strictEqual( out.map.key_0, 'new_val_0', 'replaced map value matches' );
	t.strictEqual( out.map.key_49, 'val_49', 'unreplaced map value matches' );

	// Original base must remain empty:
	t.strictEqual( base.counters.length, 0, 'original counters empty' );
	t.strictEqual( Object.keys( base.map ).length, 0, 'original map empty' );
	t.strictEqual( base.history.length, 0, 'original history empty' );
	t.end();
});


